_PINNED_DIGEST = '9a8b6a55aaf56f7c45243effb712cc3177e19cfc9984eff052f35e4017ab1dcf'

def validate_reference(ref):
    if type(ref) is not dict or set(ref)!={'id','version','contentDigest'}:raise ValueError('Skill reference')
    if type(ref['id']) is not str or not re.fullmatch('[a-z][a-z0-9.-]{0,99}',ref['id']):raise ValueError('Skill id')
    if type(ref['version']) is not str or len(ref['version'])>32 or not re.fullmatch(r'[0-9]+\.[0-9]+\.[0-9]+',ref['version']):raise ValueError('Skill version')
    if type(ref['contentDigest']) is not str or not re.fullmatch('[0-9a-f]{64}',ref['contentDigest']):raise ValueError('Skill digest')
    return copy.deepcopy(ref)

def reference(manifest):
    return validate_reference({'id':manifest['id'],'version':manifest['version'],'contentDigest':e.digest(manifest)})

def current_manifest():
    from .pi_transcript_host import MAX_MODELS,MAX_TOOLS,MAX_SECONDS
    manifest=json.loads(_MANIFEST_JSON)
    if e.digest(manifest)!=_PINNED_DIGEST or manifest['tools']!=transport.TOOL_SCHEMAS or manifest['limits']!={'modelCalls':MAX_MODELS,'toolCalls':MAX_TOOLS,'seconds':MAX_SECONDS}:raise ValueError('Trusted Skill changed')
    return manifest

def verify_current_snapshot(manifest):
    if manifest!=current_manifest():raise ValueError('Skill execution snapshot changed')
    return reference(manifest)
